const art = (a, b, label, k = 0) => `<svg class="os-pic" viewBox="0 0 400 260" role="img" aria-label="${esc(label)}" preserveAspectRatio="xMidYMid slice"><rect width="400" height="260" fill="${a}"/><circle cx="${80 + k * 60}" cy="90" r="46" fill="${b}" opacity=".9"/><rect x="${190 - k * 20}" y="60" width="150" height="110" fill="${b}" opacity=".35"/><path d="M0 210C80 170 150 230 240 200S350 170 400 205V260H0z" fill="${b}" opacity=".6"/></svg>`;
